class EpistemicExpectationProposalError(RuntimeError):
    def __init__(self, reasons: list[str] | tuple[str, ...] | set[str]) -> None:
        self.reasons = tuple(sorted({str(reason) for reason in reasons if reason}))
        super().__init__(";".join(self.reasons or ("UNSPECIFIED_EXPECTATION_FAILURE",)))


def _require_equal(actual: Any, expected: Any, reason: str) -> None:
    if actual != expected:
        raise EpistemicExpectationProposalError([reason])


def _with_content_sha(payload: dict[str, Any], *, domain: str) -> dict[str, Any]:
    output = dict(payload)
    output.pop("content_sha256", None)
    output["content_sha256"] = framed_sha256(domain, output)
    return output


def _read_exact_json(
    path: Path,
    *,
    expected_bytes: int,
    expected_sha256: str,
    label: str,
    allow_large_hash_pinned_predecessor: bool = False,
) -> dict[str, Any]:
    candidate = Path(path)
    before = candidate.lstat()
    if (
        not stat.S_ISREG(before.st_mode)
        or stat.S_ISLNK(before.st_mode)
        or before.st_nlink != 1
        or before.st_size != expected_bytes
    ):
        raise EpistemicExpectationProposalError([f"unsafe_or_wrong_file:{label}"])
    descriptor = os.open(
        candidate,
        os.O_RDONLY | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0),
    )
    try:
        raw = bytearray()
        while len(raw) <= expected_bytes:
            chunk = os.read(
                descriptor,
                min(1024 * 1024, expected_bytes + 1 - len(raw)),
            )
            if not chunk:
                break
            raw.extend(chunk)
        after = os.fstat(descriptor)
    finally:
        os.close(descriptor)
    if (
        len(raw) != expected_bytes
        or hashlib.sha256(raw).hexdigest() != expected_sha256
        or (before.st_dev, before.st_ino, before.st_size, before.st_mtime_ns)
        != (after.st_dev, after.st_ino, after.st_size, after.st_mtime_ns)
    ):
        raise EpistemicExpectationProposalError([f"identity_mismatch:{label}"])
    if allow_large_hash_pinned_predecessor:
        def _reject_duplicate_pairs(
            pairs: list[tuple[str, Any]],
        ) -> dict[str, Any]:
            result: dict[str, Any] = {}
            for key, value in pairs:
                if key in result:
                    raise ValueError(f"duplicate_json_key:{key}")
                result[key] = value
            return result

        def _reject_nonfinite(token: str) -> None:
            raise ValueError(f"nonfinite_json_number:{token}")

        try:
            payload = json.loads(
                bytes(raw).decode("utf-8"),
                object_pairs_hook=_reject_duplicate_pairs,
                parse_constant=_reject_nonfinite,
            )
        except (UnicodeError, json.JSONDecodeError, ValueError) as exc:
            raise EpistemicExpectationProposalError(
                [f"unreadable_large_frozen_json:{label}"]
            ) from exc
    else:
        payload = strict_json_loads(bytes(raw), label=label)
    if not isinstance(payload, dict):
        raise EpistemicExpectationProposalError([f"json_object_required:{label}"])
    return payload


def _read_exact_bytes(
    path: Path,
    *,
    expected_bytes: int,
    expected_sha256: str,
    label: str,
) -> bytes:
    candidate = Path(path)
    before = candidate.lstat()
    if (
        not stat.S_ISREG(before.st_mode)
        or stat.S_ISLNK(before.st_mode)
        or before.st_nlink != 1
        or before.st_size != expected_bytes
    ):
        raise EpistemicExpectationProposalError([f"unsafe_or_wrong_file:{label}"])
    descriptor = os.open(
        candidate,
        os.O_RDONLY | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0),
    )
    try:
        raw = bytearray()
        while len(raw) <= expected_bytes:
            chunk = os.read(
                descriptor,
                min(1024 * 1024, expected_bytes + 1 - len(raw)),
            )
            if not chunk:
                break
            raw.extend(chunk)
        after = os.fstat(descriptor)
    finally:
        os.close(descriptor)
    if (
        len(raw) != expected_bytes
        or hashlib.sha256(raw).hexdigest() != expected_sha256
        or (before.st_dev, before.st_ino, before.st_size, before.st_mtime_ns)
        != (after.st_dev, after.st_ino, after.st_size, after.st_mtime_ns)
    ):
        raise EpistemicExpectationProposalError([f"identity_mismatch:{label}"])
    return bytes(raw)


def _load_b0b1_r2_packet(
    manifest_path: Path,
    *,
    contracts: FrozenBootstrapContracts,
) -> tuple[dict[str, Any], dict[str, Any], dict[str, Any]]:
    manifest_path = Path(manifest_path)
    manifest = _read_exact_json(
        manifest_path,
        expected_bytes=B0B1_R2_MANIFEST_BYTES,
        expected_sha256=B0B1_R2_MANIFEST_SHA256,
        label="b0b1_r2_manifest",
    )
    expected_state = {
        "packet_id": B0B1_R2_PACKET_ID,
        "manifest_status": (
            "B0_B1_SCAFFOLD_COMPLETE__EXPECTATION_AUTHORITY_UNBOUND_BLOCKING"
        ),
        "artifact_count": 5,
        "candidate_layout_slot_count": 261,
        "candidate_materialized_case_count": 0,
        "candidate_obligation_executed_count": 0,
        "formal_mandatory_obligation_executed_count": 0,
        "formal_preflight_satisfied": False,
        "review_eligible": False,
        "live_ceremony_authorized": False,
        "permissions_opened_count": 0,
        "authority_effect": AUTHORITY_EFFECT,
    }
    for key, value in expected_state.items():
        _require_equal(manifest.get(key), value, f"b0b1_state:{key}")
    rows = manifest.get("ordered_artifacts")
    if not isinstance(rows, list) or len(rows) != 5:
        raise EpistemicExpectationProposalError(["b0b1_artifact_rows"])
    expected_names = {"packet_manifest.json"}
    loaded: dict[str, dict[str, Any]] = {}
    for ordinal, row in enumerate(rows):
        if not isinstance(row, dict) or row.get("ordinal") != ordinal:
            raise EpistemicExpectationProposalError([f"b0b1_artifact_row:{ordinal}"])
        name = row.get("path")
        if not isinstance(name, str) or "/" in name or name in {"", ".", ".."}:
            raise EpistemicExpectationProposalError([f"b0b1_artifact_path:{ordinal}"])
        expected_names.add(name)
        loaded[str(row.get("role"))] = _read_exact_json(
            manifest_path.parent / name,
            expected_bytes=int(row.get("bytes", -1)),
            expected_sha256=str(row.get("sha256", "")),
            label=f"b0b1_artifact:{ordinal}",
        )
    _require_equal(
        {entry.name for entry in manifest_path.parent.iterdir()},
        expected_names,
        "b0b1_directory_closure",
    )
    gap = loaded.get("B0B_EXPECTATION_GAP_LEDGER")
    layout = loaded.get("B0B_EXACT261_LAYOUT")
    if not isinstance(gap, dict) or not isinstance(layout, dict):
        raise EpistemicExpectationProposalError(["b0b1_required_artifacts"])
    validate_b0b_expectation_gap_ledger(gap, contracts=contracts)
    validate_b0b_exact261_layout_scaffold(
        layout,
        contracts=contracts,
        gap_ledger=gap,
    )
    return manifest, gap, layout


