        for step in spec["closed_derivation_program_ast"]:
            typed_inputs = []
            predecessor_output_ids = []
            for input_ordinal, input_field in enumerate(
                step["ordered_input_fields"]
            ):
                producer_field = input_field.split(".", 1)[0]
                producer_output_id = produced_output_id_by_field.get(
                    producer_field
                )
                if producer_output_id is None:
                    if input_field not in selector_inputs:
                        raise EpistemicExpectationProposalError(
                            [
                                "evidence_target_profile_undefined_input:"
                                f"{spec['profile_id']}:{step['step_ordinal']}:"
                                f"{input_field}"
                            ]
                        )
                    input_source_kind = "FROZEN_SELECTOR_INPUT"
                else:
                    input_source_kind = "PRIOR_STEP_OUTPUT"
                    predecessor_output_ids.append(producer_output_id)
                typed_inputs.append(
                    {
                        "input_ordinal": input_ordinal,
                        "field_name": input_field,
                        "source_kind": input_source_kind,
                        "producer_output_id": producer_output_id,
                    }
                )
            typed_outputs = []
            for output_ordinal, output_field in enumerate(
                step["ordered_output_fields"]
            ):
                output_id = (
                    f"{spec['profile_id']}::STEP{step['step_ordinal']}::"
                    f"{output_field}"
                )
                if output_field in produced_output_id_by_field:
                    raise EpistemicExpectationProposalError(
                        [
                            "evidence_target_profile_duplicate_output:"
                            f"{spec['profile_id']}:{output_field}"
                        ]
                    )
                produced_output_id_by_field[output_field] = output_id
                typed_outputs.append(
                    {
                        "output_ordinal": output_ordinal,
                        "field_name": output_field,
                        "output_id": output_id,
                    }
                )
            closed_typed_ast.append(
                {
                    **step,
                    "ordered_typed_inputs": typed_inputs,
                    "ordered_typed_outputs": typed_outputs,
                    "ordered_predecessor_output_ids": sorted(
                        set(predecessor_output_ids)
                    ),
                    "caller_supplied_intermediate_allowed": False,
                }
            )
