    def _select_evidence_authority_rule(evidence_id: str) -> dict[str, Any]:
        matches = []
        for row in evidence_authority_rule_rows:
            if row["selector_kind"] == "EXACT_SET":
                matched = evidence_id in row["selector_values"]
            else:
                matched = any(
                    evidence_id.startswith(prefix)
                    for prefix in row["selector_values"]
                )
            if matched:
                matches.append(row)
        if len(matches) != 1:
            raise EpistemicExpectationProposalError(
                [f"evidence_authority_rule_exact_one:{evidence_id}:{len(matches)}"]
            )
        return matches[0]

