    def _negative_target(family_id: str) -> tuple[str, int | None]:
        for predicate_ordinal, family_ids in negative_predicate_groups.items():
            if family_id in family_ids:
                return "PREDICATE", predicate_ordinal
        if family_id in preflight_semantics_families:
            return "PREFLIGHT_SEMANTICS", None
        if family_id in preflight_signature_families:
            return "PREFLIGHT_SIGNATURE", None
        if family_id in report_boundary_families:
            return "REPORT_OR_AUTHORITY_BOUNDARY", None
        raise EpistemicExpectationProposalError(
            [f"negative_family_target_unassigned:{family_id}"]
        )

    def _negative_mutation_operator(family_id: str) -> str:
        if family_id == "INDEPENDENT_SOD_VALIDATOR_BINDING_MISSING":
            return "REPLACE_EXACT_ONE_VALUE"
        if family_id == "CAS_RAW_READBACK_ALTERNATE_DIGEST_DOMAIN":
            return "REPLACE_EXACT_ONE_VALUE"
        if "CIRCULAR" in family_id:
            return "ADD_EXACT_ONE_BACKEDGE"
        if "REORDERED" in family_id or "ORDER_DRIFT" in family_id:
            return "SWAP_EXACT_TWO_ORDERED_VALUES"
        if "MULTI_MATCH" in family_id or any(
            token in family_id
            for token in ("EXTRA", "DUPLICATE", "SECOND_", "OVERLAP")
        ):
            return "ADD_EXACT_ONE_CONFLICTING_VALUE"
        if "MISSING" in family_id or "ZERO_MATCH" in family_id:
            return "REMOVE_EXACT_ONE_REQUIRED_VALUE"
        if "EXPIRED" in family_id:
            return "SET_EXACT_TIME_AFTER_EXPIRY"
        if "REVOKED" in family_id:
            return "SET_EXACT_REVOCATION_STATE_TRUE"
        if "SELF_CYCLE" in family_id:
            return "COPY_DOWNSTREAM_DIGEST_INTO_PREIMAGE"
        if "RAW32_REPLACED" in family_id:
            return "REPLACE_RAW32_WITH_UTF8_HEX64"
        if "ALTERNATE_DOMAIN" in family_id:
            return "REPLACE_EXACT_SIGNATURE_DOMAIN"
        if "CALLER_ASSERTED" in family_id:
            return "ADD_EXACT_ONE_FORBIDDEN_CALLER_FIELD"
        return "REPLACE_EXACT_ONE_VALUE"

    def _negative_failure_state(family_id: str) -> str:
        if family_id == "CAS_RAW_READBACK_ALTERNATE_RESOLVER_PROFILE":
            return "UNKNOWN_PROFILE_OR_ISSUER"
        if "ZERO_MATCH" in family_id or "MISSING" in family_id:
            return "ZERO_MATCH"
        if "MULTI_MATCH" in family_id:
            return "MULTI_MATCH"
        if any(token in family_id for token in ("JSON_PARSE", "DUPLICATE_JSON")):
            return "UNPARSEABLE"
        if "EXPIRED" in family_id:
            return "EXPIRED"
        if "REVOKED" in family_id:
            return "REVOKED"
        if any(
            token in family_id
            for token in ("SIGNATURE", "TRUST", "NONREVOCATION", "RAW32")
        ):
            return "SIGNATURE_OR_TRUST_INVALID"
        if "MEASUREMENT" in family_id or "IMPLEMENTATION_CODE" in family_id:
            return "MEASUREMENT_MISMATCH"
        if any(token in family_id for token in ("LINEAGE", "SCOPE", "CROSS_")):
            return "LINEAGE_OR_SCOPE_MISMATCH"
        if any(token in family_id for token in ("RAW_HASH", "SHA_MISMATCH")):
            return "RAW_OR_CONTENT_DIGEST_MISMATCH"
        return "SEMANTIC_MISMATCH"

