    def _predicate_result_schema(
        predicate_ordinal: int,
        *,
        satisfied: bool,
    ) -> dict[str, Any]:
        predicate_id, operator, input_pointers = (
            fixture_validation_predicate_specs[predicate_ordinal]
        )
        return _closed_object_schema(
            {
                "predicate_ordinal": {"const": predicate_ordinal},
                "predicate_id": {"const": predicate_id},
                "operator_semantics_id": {"const": operator},
                "predicate_semantics_row_sha256": {
                    "const": predicate_semantics_rows[predicate_ordinal][
                        "semantics_row_sha256"
                    ]
                },
                "ordered_input_json_pointers": {"const": list(input_pointers)},
                "expected_state": {"const": "SATISFIED"},
                "observed_state": (
                    {"const": "SATISFIED"}
                    if satisfied
                    else {
                        "enum": [
                            "MISSING",
                            "ZERO_MATCH",
                            "MULTI_MATCH",
                            "UNPARSEABLE",
                            "UNKNOWN_PROFILE_OR_ISSUER",
                            "RAW_OR_CONTENT_DIGEST_MISMATCH",
                            "SIGNATURE_OR_TRUST_INVALID",
                            "EXPIRED",
                            "REVOKED",
                            "LINEAGE_OR_SCOPE_MISMATCH",
                            "MEASUREMENT_MISMATCH",
                            "SEMANTIC_MISMATCH",
                        ]
                    }
                ),
                "failure_reason": (
                    {"type": "null"} if satisfied else nonempty
                ),
                "resolved_input_manifest_sha256": hex64,
                "predicate_evidence_manifest_sha256": hex64,
                "local_verdict": {
                    "const": (
                        "LOCAL_STRUCTURAL_PASS__NOT_EXECUTION"
                        if satisfied
                        else "BLOCKED"
                    )
                },
                "predicate_result_row_sha256": hex64,
            }
        )

