    def _json_pointer_escape(token: str) -> str:
        return token.replace("~", "~0").replace("/", "~1")

    def _schema_node_at_instance_pointer(
        schema_node: dict[str, Any],
        instance_pointer: str,
        *,
        nested_branch_ordinals: dict[str, int],
    ) -> dict[str, Any]:
        current = schema_node
        traversed = ""
        for encoded_token in instance_pointer.split("/")[1:]:
            token = encoded_token.replace("~1", "/").replace("~0", "~")
            if "oneOf" in current:
                branch_ordinal = nested_branch_ordinals.get(traversed)
                if branch_ordinal is None:
                    _require_equal(
                        len(current["oneOf"]),
                        1,
                        f"negative_preservation_nested_branch_required:{traversed}",
                    )
                    branch_ordinal = 0
                current = current["oneOf"][branch_ordinal]
            if "properties" in current:
                current = current["properties"][token]
            elif "prefixItems" in current:
                current = current["prefixItems"][int(token)]
            else:
                raise EpistemicExpectationProposalError(
                    [f"negative_preservation_pointer_unresolvable:{instance_pointer}"]
                )
            traversed = f"{traversed}/{encoded_token}"
        if "oneOf" in current and traversed in nested_branch_ordinals:
            current = current["oneOf"][nested_branch_ordinals[traversed]]
        return current

    def _closed_schema_leaf_pointers(
        schema_node: dict[str, Any],
        *,
        instance_pointer: str,
        nested_branch_ordinals: dict[str, int],
    ) -> list[str]:
        if "oneOf" in schema_node:
            branch_ordinal = nested_branch_ordinals.get(instance_pointer)
            if branch_ordinal is None:
                if len(schema_node["oneOf"]) != 1:
                    return [instance_pointer]
                branch_ordinal = 0
            return _closed_schema_leaf_pointers(
                schema_node["oneOf"][branch_ordinal],
                instance_pointer=instance_pointer,
                nested_branch_ordinals=nested_branch_ordinals,
            )
        if "properties" in schema_node:
            pointers: list[str] = []
            for property_name in sorted(schema_node["properties"]):
                child_pointer = (
                    f"{instance_pointer}/{_json_pointer_escape(property_name)}"
                )
                pointers.extend(
                    _closed_schema_leaf_pointers(
                        schema_node["properties"][property_name],
                        instance_pointer=child_pointer,
                        nested_branch_ordinals=nested_branch_ordinals,
                    )
                )
            return pointers
        if "prefixItems" in schema_node:
            pointers = []
            for item_ordinal, item_schema in enumerate(schema_node["prefixItems"]):
                pointers.extend(
                    _closed_schema_leaf_pointers(
                        item_schema,
                        instance_pointer=f"{instance_pointer}/{item_ordinal}",
                        nested_branch_ordinals=nested_branch_ordinals,
                    )
                )
            return pointers
        if "allOf" in schema_node:
            return sorted(
                {
                    pointer
                    for child_schema in schema_node["allOf"]
                    for pointer in _closed_schema_leaf_pointers(
                        child_schema,
                        instance_pointer=instance_pointer,
                        nested_branch_ordinals=nested_branch_ordinals,
                    )
                }
            )
        return [instance_pointer]

