    legacy_digest_profiles = core.pop("digest_profiles")
    profile_source_by_id: dict[str, dict[str, Any]] = {}
    bootstrap_profile_definition_sha256_by_id: dict[str, str] = {}
    for profile in runtime_commitment_digest_profile_sources:
        profile_id = profile["profile_id"]
        profile_source_by_id[profile_id] = dict(profile)
        bootstrap_profile_definition_sha256_by_id[profile_id] = profile[
            "profile_content_sha256"
        ]
    legacy_profile_key_by_id: dict[str, str] = {}
    runtime_profile_source_ids = {
        profile["profile_id"]
        for profile in runtime_commitment_digest_profile_sources
    }
    for legacy_key, legacy_profile in legacy_digest_profiles.items():
        profile_id = legacy_profile.get("profile_id")
        if not isinstance(profile_id, str) or profile_id in {
            "FF_E1_R11_RUNTIME_COMMITMENT_DIGEST_PROFILE_REGISTRY_V1",
        }:
            continue
        legacy_profile_key_by_id[profile_id] = legacy_key
        if profile_id in runtime_profile_source_ids:
            merged_source = dict(legacy_profile)
            merged_source.update(profile_source_by_id[profile_id])
        else:
            merged_source = dict(profile_source_by_id.get(profile_id, {}))
            merged_source.update(legacy_profile)
        profile_source_by_id[profile_id] = merged_source
    for signature_profile in external_signature_profiles:
        profile_source_by_id[signature_profile["profile_id"]] = {
            "profile_id": signature_profile["profile_id"],
            "domain": signature_profile["preimage_domain"],
            "digest_kind": "EXACT_SIGNED_SCHEMA_BRANCH_PREIMAGE",
            "canonicalization": "RFC8785_INTEGER_ONLY",
            "formula": (
                "SHA256(UTF8(domain)||0x00||RFC8785("
                "exact_closed_preimage_projection))"
            ),
            "depends_on_profile_ids": [],
        }
        profile_source_by_id.setdefault(
            signature_profile["content_digest_profile_id"],
            {
                "profile_id": signature_profile[
                    "content_digest_profile_id"
                ],
                "domain": signature_profile["content_domain"],
                "digest_kind": "SIGNED_ENVELOPE_CONTENT",
                "canonicalization": "RFC8785_INTEGER_ONLY",
                "formula": (
                    "SHA256(UTF8(domain)||0x00||RFC8785("
                    "exact_closed_signed_envelope_without_content_sha256))"
                ),
                "depends_on_profile_ids": [signature_profile["profile_id"]],
            },
        )

    explicit_digest_target_bindings_by_profile_id: dict[
        str, list[dict[str, Any]]
    ] = {}

    def _ensure_digest_profile_source(
        profile_id: str,
        *,
        digest_kind: str,
        canonicalization: str = "RFC8785_INTEGER_ONLY",
        hash_construction: str | None = None,
        dependency_profile_ids: list[str] | None = None,
    ) -> None:
        profile_source_by_id.setdefault(
            profile_id,
            {
                "profile_id": profile_id,
                "domain": profile_id,
                "digest_kind": digest_kind,
                "canonicalization": canonicalization,
                "formula": hash_construction
                or (
                    "SHA256(UTF8(domain)||0x00||RFC8785("
                    "exact_closed_preimage_projection))"
                ),
                "depends_on_profile_ids": dependency_profile_ids or [],
            },
        )

    def _append_digest_target_binding(
        profile_id: str,
        *,
        target_locator: str,
        digest_output_json_pointer: str,
        ordered_preimage_json_pointers: list[str],
        target_branch_ordinal: int | None = None,
        binding_kind: str = "EXACT_CLOSED_OBJECT",
    ) -> None:
        binding = {
            "binding_kind": binding_kind,
            "target_locator": target_locator,
            "target_branch_ordinal": target_branch_ordinal,
            "digest_output_json_pointer": digest_output_json_pointer,
            "ordered_preimage_json_pointers": (
                ordered_preimage_json_pointers
            ),
            "wildcard_or_ambient_field_selection_allowed": False,
        }
        binding_id = canonicalize(binding)
        existing = explicit_digest_target_bindings_by_profile_id.setdefault(
            profile_id, []
        )
        if all(canonicalize(row) != binding_id for row in existing):
            existing.append(binding)

    def _append_row_and_manifest_digest_bindings(
        *,
        row_profile_id: str,
        manifest_profile_id: str,
        registry_pointer: str,
        ordered_rows: list[dict[str, Any]],
        row_digest_field: str,
    ) -> None:
        _ensure_digest_profile_source(
            row_profile_id,
            digest_kind="CLOSED_REGISTRY_ROW",
        )
        _ensure_digest_profile_source(
            manifest_profile_id,
            digest_kind="ORDERED_CHILD_DIGEST_MANIFEST",
            canonicalization="ORDERED_RAW32_CONCATENATION",
            hash_construction=(
                "SHA256(UTF8(domain)||0x00||"
                "CONCAT(ordered_child_digest_raw32))"
            ),
            dependency_profile_ids=[row_profile_id],
        )
        for row_ordinal, row in enumerate(ordered_rows):
            _append_digest_target_binding(
                row_profile_id,
                target_locator=f"{registry_pointer}/{row_ordinal}",
                target_branch_ordinal=row_ordinal,
                digest_output_json_pointer=f"/{row_digest_field}",
                ordered_preimage_json_pointers=[
                    f"/{_json_pointer_escape(field_name)}"
                    for field_name in sorted(row)
                    if field_name != row_digest_field
                ],
            )
        _append_digest_target_binding(
            manifest_profile_id,
            target_locator=registry_pointer,
            digest_output_json_pointer="/@ordered_manifest_sha256",
            ordered_preimage_json_pointers=[
                f"/{row_ordinal}/{row_digest_field}"
                for row_ordinal in range(len(ordered_rows))
            ],
            binding_kind="ORDERED_CHILD_DIGEST_MANIFEST",
        )

